 "content": "def transform(grid):
    """Mark each panel containing at least two non-background pixels."""
    h, w = len(grid), len(grid[0])

    # The uniform separator lines divide the grid into rectangular panels.
    sep_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    row_edges = [-1] + sep_rows + [h]
    col_edges = [-1] + sep_cols + [w]

    separator_colors = {grid[r][0] for r in sep_rows}
    separator_colors.update(grid[0][c] for c in sep_cols)
    counts = {}
    for row in grid:
        for color in row:
            if color not in separator_colors:
                counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)

    output = []
    for r0, r1 in zip(row_edges, row_edges[1:]):
        result_row = []
        for c0, c1 in zip(col_edges, col_edges[1:]):
            non_background = sum(
                grid[r][c] != background
                for r in range(r0 + 1, r1)
                for c in range(c0 + 1, c1)
            )
            result_row.append(1 if non_background >= 2 else background)
        output.append(result_row)
    return output
